// r13-merge: per-workload dispatch over 9 unchanged kernels (loop/merge.py).
//   r8-d-e1-allwarp-epi: 8,384,14,14; r9-g-e3-tc05-p1s: 8,320,32,32; r10-d-e1-balanced-nostack: 8,768,7,7 16,768,7,7; r11-d-e1-g2-mp2-bulk: 2,768,7,7; r12-d-e2-grn-epi-counters: 32,768,7,7; r13-m-e4-token-stationary: 2,96,56,56; r13-i-e3-rows-tail: 64,96,112,112 32,128,64,64; r13-d-e2-sc-stripconv-512: 1,160,449,7 4,96,56,56 1,96,56,56 4,192,28,28 1,192,28,28 8,192,28,28 (+ any other shape); r13-d-e1-balanced-ranges-h49: 16,384,14,14
#include <torch/extension.h>
#include <cstdint>

