  if (!enc16(&p.mW2, p.w2h, C4, C, 64, 128)) return "ws_launch: map W2";
  if (!enc16(&p.mD, p.d16, pl.Mcols, C, 64, 64)) return "ws_launch: map D";
  if (!enc16(&p.mH, p.hid, pl.Mcols, C4, 64, 64)) return "ws_launch: map H";
